0:
{
    admin off
    auto_https off
    servers {
        # Keep X-Forwarded-Proto/For set by Envoy
        trusted_proxies static private_ranges
    }
}

:9090 {
    respond /healthz 200
}

:8080 {
    log
    encode gzip
    request_body {
        max_size 100MB
    }

    handle_path /static/* {
        header Access-Control-Allow-Origin *
        header Access-Control-Allow-Methods GET,HEAD,OPTIONS
        header Access-Control-Allow-Headers Authorization,Content-Type,User-Agent,traceparent
        @preflight method OPTIONS
        respond @preflight 204
        root * /static
        file_server
    }

    # Media is only served after gunicorn confirms the session (/auth/)
    handle_path /media/* {
        root * /media
        file_server
        header Content-Disposition attachment
        forward_auth 127.0.0.1:8000 {
            uri /auth/
        }
    }

    reverse_proxy 127.0.0.1:8000
}
